(1, 1, 'Nephrology Nursing Mock — Day 4 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'CVVH (continuous venovenous haemofiltration) removes solutes mainly by:', '["Osmosis", "Adsorption only", "Convection", "Diffusion only"]'::jsonb, 2, 'CVVHD uses diffusion; CVVHDF uses both.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 2, 'Nephrology Nursing Mock — Day 4 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Selling or buying organs for transplantation is:', '["Allowed if both agree", "Encouraged to increase donors", "Required by law", "Illegal and unethical"]'::jsonb, 3, 'Organ trafficking exploits vulnerable people.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 3, 'Nephrology Nursing Mock — Day 4 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'Which of the following is the best practice to reduce infection risk in peritoneal dialysis patients?', '["Blood pressure monitoring", "Use of heparin", "High protein diet", "Regular handwashing"]'::jsonb, 3, 'Proper hand hygiene is crucial to prevent peritoneal dialysis infections.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
(1, 4, 'Nephrology Nursing Mock — Day 4 Morning (Nov 2026)', 'NNP 420 · Principles & Practice of Nephrology Nursing II', 'The three phases of a PD exchange are:', '["Clamp, push and pull", "Pump, filter and return", "Bleed, rinse and dry", "Drain, fill and dwell"]'::jsonb, 3, 'Draining first removes the used fluid.', 'NNP 420 · Principles & Practice of Nephrology Nursing II'),
